            pa: '2 ਸਤੰਬਰ 2023 ਨੂੰ PSLV-C57 ਰਾਹੀਂ ਲਾਂਚ ਕੀਤਾ ਗਿਆ ਆਦਿਤਿਆ-L1 ਧਰਤੀ ਤੋਂ 15 ਲੱਖ ਕਿਲੋਮੀਟਰ ਦੂਰ Lagrange Point 1 (L1) ਦੇ ਹੇਲੋ ਆਰਬਿਟ ਵਿੱਚ ਸਥਾਪਿਤ ਕੀਤਾ ਗਿਆ ਹੈ, ਜਿੱਥੋਂ ਬਿਨਾਂ ਕਿਸੇ ਗ੍ਰਹਿਣ ਦੇ ਸੂਰਜ ਦਾ ਲਗਾਤਾਰ ਅਧਿਐਨ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।',
            hi: '2 सितंबर 2023 को PSLV-C57 से प्रक्षेपित आदित्य-L1 को पृथ्वी से 15 लाख किमी दूर Lagrange Point 1 (L1) के हेलो ऑर्बिट में स्थापित किया गया है, जहाँ से बिना किसी ग्रहण के सूर्य का निरंतर अध्ययन संभव है।'
