            pa: 'ਘਰੇਲੂ ਬਿਜਲੀ ਸਰਕਟਾਂ ਵਿੱਚ ਲੜੀਵਾਰ (Series) ਲਗਾਈ ਜਾਣ ਵਾਲੀ ਫਿਊਜ਼ ਤਾਰ ਸਿੱਕੇ ਅਤੇ ਟਿਨ (Pb + Sn) ਦੀ ਮਿਸ਼ਰਤ ਧਾਤ ਤੋਂ ਬਣੀ ਹੁੰਦੀ ਹੈ; ਇਸ ਦੇ ਜ਼ਰੂਰੀ ਭੌਤਿਕ ਗੁਣ ਕੀ ਹੋਣੇ ਚਾਹੀਦੇ ਹਨ?',
