            B: { en: 'Low melting point and high specific resistance (resistivity)', pa: 'ਘੱਟ ਪਿਘਲਣ ਦਰਜਾ (Low melting point) ਅਤੇ ਉੱਚ ਪ੍ਰਤੀਰੋਧ (High resistance)', hi: 'निम्न गलनांक (Low melting point) और उच्च प्रतिरोधकता (High resistance)' },
