            hi: 'निम्नलिखित मिश्रधातुओं (Alloys) का उनके घटक धातुओं से मिलान कीजिए: (1) पीतल (Brass), (2) कांसा (Bronze), (3) टांका / सोल्डर (Solder), (4) जर्मन सिल्वर (German Silver)।'
