            hi: 'लोहे को जंग लगने से बचाने के लिए "यशदलेपन / गैल्वनीकरण" (Galvanization) प्रक्रिया में लोहे पर किस धातु की परत चढ़ाई जाती है, और स्वस्थ मानव रक्त का सामान्य pH मान कितना होता है?'
