            B: { en: 'Zinc (Zn); pH 7.4 (slightly alkaline)', pa: 'ਜ਼ਿੰਕ / ਜਸਤਾ (Zn); pH 7.4 (ਹਲਕਾ ਖਾਰਾ)', hi: 'जस्ता / ज़िंक (Zn); pH 7.4 (हल्का क्षारीय)' },
            C: { en: 'Tin (Sn); pH 7.0 (neutral)', pa: 'ਟਿਨ (Sn); pH 7.0', hi: 'टिन (Sn); pH 7.0' },
            D: { en: 'Aluminium (Al); pH 8.5', pa: 'ਐਲੂਮੀਨੀਅਮ (Al); pH 8.5', hi: 'एल्युमिनियम (Al); pH 8.5' }
